use std::{path::Path, time::Instant};
use gwt::cli::execution_state::{self as execution, ExecutionOwnerKey};

fn observe(path: &Path, owner: ExecutionOwnerKey, duplicate: bool) -> (u128, usize) {
    let started = Instant::now();
    let mut additional_validations = 0;
    for _ in 0..12 {
        let ledger = execution::load_generation_ledger(path, owner).unwrap().unwrap();
        if duplicate {
            additional_validations += 1;
            assert!(execution::generation_ledger_integrity_ok(&ledger));
        }
        std::hint::black_box(ledger);
    }
    (started.elapsed().as_nanos(), additional_validations)
}

fn main() {
    let arg = std::env::args().nth(1).unwrap();
    let path = Path::new(&arg);
    let record = execution::load(path).unwrap().unwrap();
    assert!(execution::integrity_ok(&record));
    let owner = ExecutionOwnerKey { kind: record.owner_kind, number: record.owner_number };
    let ledger = execution::load_generation_ledger(path, owner).unwrap().unwrap();
    println!("{{\"kind\":\"input\",\"record_hash\":\"{}\",\"ledger_hash\":\"{}\",\"generations\":{},\"strict_loads_per_sample\":12,\"paired_rounds\":20}}", record.content_hash, ledger.content_hash, ledger.generations.len());
    observe(path, owner, true);
    observe(path, owner, false);
    for round in 0..20 {
        let (old, new) = if round % 2 == 0 {
            (observe(path, owner, true), observe(path, owner, false))
        } else {
            let new = observe(path, owner, false);
            (observe(path, owner, true), new)
        };
        println!("{{\"kind\":\"pair\",\"round\":{round},\"old_ns\":{},\"old_additional_validations\":{},\"new_ns\":{},\"new_additional_validations\":{}}}",old.0,old.1,new.0,new.1);
    }
    let after = execution::load(path).unwrap().unwrap();
    let after_ledger = execution::load_generation_ledger(path, owner).unwrap().unwrap();
    assert_eq!(record.content_hash, after.content_hash, "input changed");
    assert_eq!(ledger.content_hash, after_ledger.content_hash, "ledger changed");
    assert_eq!(ledger, after_ledger, "loaded ledger changed");
    println!("{{\"kind\":\"validated\",\"input_unchanged\":true}}");
}
